/* Generated by scripts/split-content.mjs — do not edit by hand.
   The glossary and a sample of the question bank. The rest is served
   from the content function once entitlement is confirmed. */
window.DATA = {"cards":[{"id":"c000","term":"Real Property","def":"Land, anything permanently attached to it (improvements), and the rights associated with ownership. Distinguished from personal property (chattels).","cat":"Property"},{"id":"c001","term":"Personal Property (Chattels)","def":"Movable items not permanently attached to land. A chandelier is a fixture (real property); a floor lamp is personal property.","cat":"Property"},{"id":"c002","term":"Fixture","def":"Personal property that has been permanently attached to real property and is now considered part of it. Determined by method of attachment, adaptation, intent, and agreement.","cat":"Property"},{"id":"c003","term":"Trade Fixture","def":"Items installed by a commercial tenant for business use. Remain the tenant's personal property and may be removed before lease expiration.","cat":"Property"},{"id":"c004","term":"Bundle of Rights","def":"The rights that come with property ownership: possession, control, enjoyment, exclusion, and disposition (sale, lease, gift, will).","cat":"Property"},{"id":"c005","term":"Fee Simple Absolute","def":"The highest form of ownership. Unlimited duration, fully inheritable, no conditions. The owner can sell, lease, encumber, or will the property.","cat":"Property"},{"id":"c006","term":"Fee Simple Defeasible","def":"Ownership that can be lost if a specified condition is violated. Determinable (automatic reversion) or subject to condition subsequent (grantor must act).","cat":"Property"},{"id":"c007","term":"Life Estate","def":"Ownership limited to the lifetime of a named person (the measuring life). The life tenant cannot commit waste. Upon death, property passes to the remainderman.","cat":"Property"},{"id":"c008","term":"Remainder vs. Reversion","def":"Remainder: a future interest held by a third party after a life estate ends. Reversion: the future interest returns to the original grantor.","cat":"Property"},{"id":"c009","term":"Tenancy in Common","def":"Co-ownership with undivided interest. Shares need not be equal. Each owner can sell or will their share independently. No right of survivorship.","cat":"Property"},{"id":"c010","term":"Joint Tenancy","def":"Co-ownership with right of survivorship. Requires four unities: time, title, interest, and possession. A deceased owner's share passes automatically to surviving owners.","cat":"Property"},{"id":"c011","term":"Tenancy by the Entirety","def":"Joint tenancy available only to married couples. Neither spouse can convey without the other's consent. Creditors of one spouse cannot attach the property.","cat":"Property"},{"id":"c012","term":"Community Property","def":"In community property states, property acquired during marriage is owned equally by both spouses. Separate property includes gifts, inheritance, and pre-marriage assets.","cat":"Property"},{"id":"c013","term":"Condominium","def":"Individual ownership of a unit plus an undivided interest in common areas. Governed by a homeowners association (HOA) with CC&Rs.","cat":"Property"},{"id":"c014","term":"Cooperative","def":"Ownership of shares in a corporation that owns the building. The shareholder receives a proprietary lease for their unit. Board approval often required for transfers.","cat":"Property"},{"id":"c015","term":"Timeshare","def":"Shared ownership or right-to-use arrangement for a property, typically a vacation unit, divided by time periods among multiple owners.","cat":"Property"},{"id":"c016","term":"Riparian Rights","def":"Water rights for landowners along a flowing waterway (river, stream). The owner may use the water reasonably without depriving downstream owners.","cat":"Property"},{"id":"c017","term":"Littoral Rights","def":"Water rights for landowners along a stationary body of water (lake, ocean). The owner has rights to the water's edge.","cat":"Property"},{"id":"c018","term":"Accretion / Erosion / Avulsion","def":"Accretion: gradual deposit of soil adding to land. Erosion: gradual loss. Avulsion: sudden loss of land by water (e.g., flood). Accretion benefits the owner.","cat":"Property"},{"id":"c019","term":"Air Rights / Subsurface Rights","def":"Ownership extends above and below the surface unless rights have been separated. Air rights can be sold or leased (common in cities).","cat":"Property"},{"id":"c020","term":"Emblements","def":"Annual crops planted by a tenant. Considered personal property of the tenant, who may harvest them even after the lease or life estate ends.","cat":"Property"},{"id":"c021","term":"Encumbrance","def":"Any claim, lien, or limitation on a property that affects its value or use but does not prevent transfer. Includes liens, easements, and deed restrictions.","cat":"Title"},{"id":"c022","term":"Lien","def":"A financial claim against property as security for a debt. Can be voluntary (mortgage) or involuntary (tax lien, mechanic's lien, judgment lien).","cat":"Title"},{"id":"c023","term":"Property Tax Lien","def":"A specific, involuntary, statutory lien. Takes priority over all other liens regardless of recording date. Failure to pay results in tax sale.","cat":"Title"},{"id":"c024","term":"Mortgage Lien","def":"A voluntary, specific lien created when a borrower pledges property as security for a loan. Recorded to establish priority.","cat":"Title"},{"id":"c025","term":"Mechanic's Lien","def":"An involuntary, specific lien filed by a contractor or supplier who performed work on the property and was not paid. Priority often dates to start of work.","cat":"Title"},{"id":"c026","term":"Judgment Lien","def":"An involuntary, general lien against all property of a debtor resulting from a court judgment. Attaches to all real property owned in the county where recorded.","cat":"Title"},{"id":"c027","term":"Easement","def":"A right to use another's land for a specific purpose. Does not convey ownership. Runs with the land unless it is in gross.","cat":"Title"},{"id":"c028","term":"Easement Appurtenant","def":"Benefits a neighboring property (dominant tenement) at the expense of another (servient tenement). Runs with both properties when sold.","cat":"Title"},{"id":"c029","term":"Easement in Gross","def":"Benefits a person or entity, not a neighboring property. Utility easements are the most common example. Does not require a dominant tenement.","cat":"Title"},{"id":"c030","term":"Easement by Necessity","def":"Created by court when a property is landlocked with no access to a public road. The landlocked parcel gets access across the surrounding land.","cat":"Title"},{"id":"c031","term":"Easement by Prescription","def":"Acquired through continuous, open, notorious, hostile, and uninterrupted use for the statutory period (similar to adverse possession but for use, not ownership).","cat":"Title"},{"id":"c032","term":"Encroachment","def":"A physical intrusion onto an adjacent property — a fence, building, or driveway that crosses the property line.","cat":"Title"},{"id":"c033","term":"Deed Restriction (CC&R)","def":"Private limitations on property use placed by a developer or HOA. Covenants, Conditions, and Restrictions run with the land and bind future owners.","cat":"Title"},{"id":"c034","term":"Lis Pendens","def":"A recorded notice that a lawsuit affecting the property is pending. Warns potential buyers that the title is in dispute.","cat":"Title"},{"id":"c035","term":"Deed","def":"The legal document that transfers title to real property. Must be in writing, signed by the grantor, and delivered and accepted to be effective.","cat":"Title"},{"id":"c036","term":"General Warranty Deed","def":"Provides the greatest protection. The grantor warrants title against all defects, including those from prior owners. Contains covenants of seisin, quiet enjoyment, and warranty.","cat":"Title"},{"id":"c037","term":"Special Warranty Deed","def":"The grantor warrants title only against defects arising during their period of ownership. Does not cover prior owners' actions.","cat":"Title"},{"id":"c038","term":"Quitclaim Deed","def":"Transfers whatever interest the grantor has, with no warranties. Provides the least protection. Commonly used between family members or to clear title defects.","cat":"Title"},{"id":"c039","term":"Title Insurance","def":"Insurance protecting against losses from title defects not discovered during the title search. Owner's policy protects the buyer; lender's policy protects the lender.","cat":"Title"},{"id":"c040","term":"Abstract of Title","def":"A condensed history of all recorded documents affecting a property's title, from the original grant to the present.","cat":"Title"},{"id":"c041","term":"Recording","def":"Filing documents (deeds, mortgages, liens) with the county recorder to provide constructive notice to the public. Priority generally goes by recording date.","cat":"Title"},{"id":"c042","term":"Chain of Title","def":"The sequential history of property ownership from the original grant to the current owner. A break in the chain creates a title defect.","cat":"Title"},{"id":"c043","term":"Adverse Possession","def":"Acquiring title to property through continuous, open, notorious, hostile, and exclusive possession for the statutory period. Requirements vary by state.","cat":"Title"},{"id":"c044","term":"Probate","def":"The legal process of settling a deceased person's estate, including transferring property. If no will exists, property passes by intestate succession.","cat":"Title"},{"id":"c045","term":"Valid Contract Elements","def":"Competent parties, mutual consent (offer and acceptance), legal purpose, and consideration. Must also comply with the Statute of Frauds (in writing for real estate).","cat":"Contracts"},{"id":"c046","term":"Statute of Frauds","def":"Requires certain contracts — including real estate — to be in writing and signed to be enforceable. Verbal real estate contracts are generally unenforceable.","cat":"Contracts"},{"id":"c047","term":"Offer and Acceptance","def":"Offer: a proposal with specific terms. Acceptance: unconditional agreement to those terms. A counteroffer terminates the original offer.","cat":"Contracts"},{"id":"c048","term":"Counteroffer","def":"A response that changes the terms of the original offer. It rejects the original offer and creates a new one. The original offeror can accept, reject, or counter again.","cat":"Contracts"},{"id":"c049","term":"Consideration","def":"Something of value exchanged between parties. In real estate, this is typically the purchase price. Earnest money demonstrates good faith but is not required for a valid contract.","cat":"Contracts"},{"id":"c050","term":"Earnest Money","def":"A deposit made by the buyer to demonstrate good faith. Held in escrow. If the buyer defaults, it may be forfeited as liquidated damages per the contract.","cat":"Contracts"},{"id":"c051","term":"Contingency","def":"A condition that must be met for the contract to proceed. Common contingencies: financing, inspection, appraisal, sale of current home. Protects the buyer's deposit.","cat":"Contracts"},{"id":"c052","term":"Option Contract","def":"The buyer pays for the right to purchase the property within a specified time at an agreed price. The seller cannot sell to anyone else during the option period.","cat":"Contracts"},{"id":"c053","term":"Specific Performance","def":"A legal remedy forcing a party to fulfill their contractual obligations. Used in real estate because each property is unique. Available to both buyers and sellers.","cat":"Contracts"},{"id":"c054","term":"Liquidated Damages","def":"An amount agreed upon in advance as compensation for breach. In real estate, typically the earnest money deposit is forfeited if the buyer defaults.","cat":"Contracts"},{"id":"c055","term":"Assignment","def":"Transferring contract rights to another party. Most real estate contracts can be assigned unless the contract specifically prohibits it.","cat":"Contracts"},{"id":"c056","term":"Novation","def":"Substituting a new contract or party for an existing one, releasing the original party from liability. Differs from assignment, where the original party may remain liable.","cat":"Contracts"},{"id":"c057","term":"Time is of the Essence","def":"A contract clause requiring strict adherence to dates and deadlines. Failure to perform on time is a material breach.","cat":"Contracts"},{"id":"c058","term":"Void vs. Voidable Contract","def":"Void: no legal effect from the beginning (illegal purpose). Voidable: valid but can be voided by one party (minor, duress, fraud). The injured party chooses.","cat":"Contracts"},{"id":"c059","term":"Unilateral vs. Bilateral Contract","def":"Unilateral: one party promises, performance by the other accepts (option). Bilateral: both parties promise (most purchase agreements).","cat":"Contracts"},{"id":"c060","term":"Agency Relationship","def":"A fiduciary relationship in which an agent acts on behalf of a principal (client). Created by agreement, ratification, or estoppel.","cat":"Agency"},{"id":"c061","term":"Fiduciary Duties","def":"OLDCAR: Obedience, Loyalty, Disclosure, Confidentiality, Accountability, Reasonable care. Owed by the agent to the principal (client).","cat":"Agency"},{"id":"c062","term":"Seller's Agent (Listing Agent)","def":"Represents the seller. Owes fiduciary duties to the seller. Must disclose material facts. Earns commission when the property sells.","cat":"Agency"},{"id":"c063","term":"Buyer's Agent","def":"Represents the buyer. Owes fiduciary duties to the buyer. Helps find properties, negotiate offers, and protect the buyer's interests.","cat":"Agency"},{"id":"c064","term":"Dual Agency","def":"One agent or brokerage represents both buyer and seller in the same transaction. Requires informed written consent from both parties. Prohibited in some states.","cat":"Agency"},{"id":"c065","term":"Transaction Broker","def":"Facilitates the transaction without representing either party. Owes honesty and fairness to both but not full fiduciary duties. Common in some states.","cat":"Agency"},{"id":"c066","term":"Disclosed vs. Undisclosed Dual Agency","def":"Disclosed: both parties consent in writing. Undisclosed: occurs without knowledge — this is illegal and voids the agent's right to a commission.","cat":"Agency"},{"id":"c067","term":"Agency Disclosure","def":"Agents must inform all parties whom they represent at the first substantive contact. State laws specify timing and form of disclosure.","cat":"Agency"},{"id":"c068","term":"Listing Agreement","def":"A contract between the seller and the broker authorizing the broker to market the property. Types: exclusive right to sell, exclusive agency, open listing.","cat":"Agency"},{"id":"c069","term":"Exclusive Right to Sell","def":"The broker earns a commission regardless of who finds the buyer, including the seller. Provides the most protection for the broker.","cat":"Agency"},{"id":"c070","term":"Exclusive Agency","def":"The broker earns a commission unless the seller finds the buyer independently. The broker is the only authorized agent but the seller retains the right to self-sell.","cat":"Agency"},{"id":"c071","term":"Open Listing","def":"The seller may list with multiple brokers. Only the broker who procures the buyer earns the commission. The seller may also sell independently.","cat":"Agency"},{"id":"c072","term":"Net Listing","def":"The broker keeps everything above a specified net amount to the seller. Illegal or discouraged in most states due to conflict of interest.","cat":"Agency"},{"id":"c073","term":"Material Facts","def":"Information that could affect a buyer's decision: structural defects, environmental hazards, neighborhood conditions, pending assessments. Must be disclosed.","cat":"Agency"},{"id":"c074","term":"Stigmatized Property","def":"A property with a negative history (death, crime, alleged haunting). Disclosure requirements vary by state. Physical defects must always be disclosed.","cat":"Agency"},{"id":"c075","term":"Procuring Cause","def":"The broker whose efforts are the primary cause of the sale. Determines commission entitlement in disputes between brokers.","cat":"Agency"},{"id":"c076","term":"Commingling","def":"Mixing client funds with the broker's personal or business funds. Illegal. Earnest money must be held in a separate escrow/trust account.","cat":"Agency"},{"id":"c077","term":"Conversion","def":"Unauthorized use of client funds by the broker. A criminal offense beyond commingling.","cat":"Agency"},{"id":"c078","term":"Mortgage","def":"A security instrument that pledges real property as collateral for a loan. The borrower (mortgagor) gives the mortgage to the lender (mortgagee).","cat":"Financing"},{"id":"c079","term":"Deed of Trust","def":"A three-party security instrument: borrower (trustor), lender (beneficiary), and neutral third party (trustee). Trustee holds title until the loan is repaid.","cat":"Financing"},{"id":"c080","term":"Promissory Note","def":"The borrower's personal promise to repay the loan. Contains the terms: amount, interest rate, payment schedule, and consequences of default. The debt instrument.","cat":"Financing"},{"id":"c081","term":"Down Payment","def":"The portion of the purchase price paid by the buyer in cash. Conventional loans typically require 3–20%. Lower down payments usually require PMI.","cat":"Financing"},{"id":"c082","term":"PMI (Private Mortgage Insurance)","def":"Insurance protecting the lender when the borrower's down payment is less than 20%. Automatically cancels at 78% LTV. Paid by the borrower.","cat":"Financing"},{"id":"c083","term":"LTV (Loan-to-Value Ratio)","def":"The loan amount divided by the property's appraised value or purchase price (whichever is lower). Higher LTV = higher risk for the lender.","cat":"Financing"},{"id":"c084","term":"Amortization","def":"The gradual repayment of a loan through scheduled payments of principal and interest. Early payments are mostly interest; later payments are mostly principal.","cat":"Financing"},{"id":"c085","term":"Fixed-Rate Mortgage","def":"Interest rate remains constant for the entire loan term. Monthly principal and interest payments are predictable. Common terms: 15 and 30 years.","cat":"Financing"},{"id":"c086","term":"Adjustable-Rate Mortgage (ARM)","def":"Interest rate adjusts periodically based on an index plus a margin. Has rate caps (periodic and lifetime). Initial rate is typically lower than fixed.","cat":"Financing"},{"id":"c087","term":"FHA Loan","def":"Government-insured loan through the Federal Housing Administration. Lower down payment (3.5%), more flexible credit requirements. Requires MIP (mortgage insurance premium).","cat":"Financing"},{"id":"c088","term":"VA Loan","def":"Government-guaranteed loan for eligible veterans and service members. No down payment required, no PMI. Funding fee applies. Certificate of Eligibility required.","cat":"Financing"},{"id":"c089","term":"Conventional Loan","def":"A loan not insured or guaranteed by the government. Conforming loans meet Fannie Mae/Freddie Mac guidelines. Non-conforming (jumbo) exceed loan limits.","cat":"Financing"},{"id":"c090","term":"RESPA (Real Estate Settlement Procedures Act)","def":"Federal law requiring lenders to disclose settlement costs. Prohibits kickbacks and referral fees. Requires Loan Estimate and Closing Disclosure.","cat":"Financing"},{"id":"c091","term":"TILA (Truth in Lending Act)","def":"Federal law requiring lenders to disclose the true cost of credit including APR, total interest, and total cost of the loan. Provides right of rescission for refinances.","cat":"Financing"},{"id":"c092","term":"Loan Estimate","def":"TRID form provided within 3 business days of loan application. Itemizes estimated loan costs, projected payments, and closing costs.","cat":"Financing"},{"id":"c093","term":"Closing Disclosure","def":"TRID form provided at least 3 business days before closing. Final itemization of all costs, replacing the HUD-1. Must be compared against the Loan Estimate.","cat":"Financing"},{"id":"c094","term":"Equity","def":"The difference between the property's market value and the outstanding mortgage balance. Builds through principal payments and appreciation.","cat":"Financing"},{"id":"c095","term":"Foreclosure","def":"The legal process by which a lender takes possession of a property when the borrower defaults. Types: judicial (court process) and non-judicial (power of sale).","cat":"Financing"},{"id":"c096","term":"Short Sale","def":"Selling a property for less than the mortgage balance with lender approval. The lender agrees to accept less than what is owed. Alternative to foreclosure.","cat":"Financing"},{"id":"c097","term":"Assumption","def":"A buyer takes over the seller's existing mortgage. FHA and VA loans may be assumable. Conventional loans typically have a due-on-sale clause preventing assumption.","cat":"Financing"},{"id":"c098","term":"Due-on-Sale Clause","def":"A mortgage provision requiring full repayment when the property is sold or transferred. Prevents assumption without lender approval.","cat":"Financing"},{"id":"c099","term":"Usury","def":"Charging interest above the legal maximum rate. Usury laws vary by state and protect borrowers from predatory lending.","cat":"Financing"},{"id":"c100","term":"Points","def":"A fee paid to the lender at closing to reduce the interest rate. One point equals 1% of the loan amount. Points are prepaid interest and may be tax-deductible.","cat":"Financing"},{"id":"c101","term":"Market Value","def":"The most probable price a property would bring in an open market with a willing buyer and seller, both informed and acting without pressure.","cat":"Valuation"},{"id":"c102","term":"Appraisal","def":"An objective estimate of a property's market value by a licensed appraiser. Required by lenders before approving a mortgage.","cat":"Valuation"},{"id":"c103","term":"Sales Comparison Approach","def":"Estimates value by comparing the subject property to recent sales of similar properties (comparables). Adjustments are made for differences. Best for residential.","cat":"Valuation"},{"id":"c104","term":"Cost Approach","def":"Estimates value by calculating the cost to replace or reproduce the improvements, minus depreciation, plus land value. Best for unique or new properties.","cat":"Valuation"},{"id":"c105","term":"Income Approach","def":"Estimates value based on the income a property generates. Uses capitalization rate (cap rate) or gross rent multiplier. Best for investment properties.","cat":"Valuation"},{"id":"c106","term":"Capitalization Rate (Cap Rate)","def":"NOI divided by value (or price). A higher cap rate implies higher risk and higher return. Used to compare investment properties.","cat":"Valuation"},{"id":"c107","term":"Gross Rent Multiplier (GRM)","def":"Sale price divided by gross monthly or annual rent. A quick screening tool for comparing rental properties. Does not account for expenses.","cat":"Valuation"},{"id":"c108","term":"Depreciation (Appraisal)","def":"Loss of value from any cause. Physical deterioration (wear and tear), functional obsolescence (outdated design), and external/economic obsolescence (location factors).","cat":"Valuation"},{"id":"c109","term":"Comparative Market Analysis (CMA)","def":"An informal estimate of value prepared by a real estate agent using recent comparable sales. Not an appraisal. Used to determine listing price.","cat":"Valuation"},{"id":"c110","term":"Assessed Value","def":"The value assigned to a property by the tax assessor for purposes of calculating property taxes. May differ from market value.","cat":"Valuation"},{"id":"c111","term":"Reconciliation","def":"The appraiser's process of weighing the values from multiple approaches to arrive at a final estimate of value.","cat":"Valuation"},{"id":"c112","term":"Highest and Best Use","def":"The legally permissible, physically possible, financially feasible, and maximally productive use of a property. The foundation of the appraisal process.","cat":"Valuation"},{"id":"c113","term":"Principle of Substitution","def":"A buyer will not pay more for a property than the cost of acquiring an equally desirable substitute. Underlies the sales comparison approach.","cat":"Valuation"},{"id":"c114","term":"Principle of Conformity","def":"Maximum value is achieved when a property conforms to the standards of its neighborhood. Over-improvement and under-improvement reduce value.","cat":"Valuation"},{"id":"c115","term":"Zoning","def":"Government regulation controlling land use within designated areas. Categories include residential, commercial, industrial, and agricultural. Can be changed through variance or rezoning.","cat":"Land Use"},{"id":"c116","term":"Variance","def":"An exception to zoning rules granted to a property owner experiencing unique hardship. Does not change the zoning classification itself.","cat":"Land Use"},{"id":"c117","term":"Nonconforming Use","def":"A property use that was legal before a zoning change but no longer complies. Typically allowed to continue (grandfathered) but cannot be expanded.","cat":"Land Use"},{"id":"c118","term":"Conditional Use Permit","def":"Permission to use property in a way not normally allowed by zoning (e.g., a church in a residential zone). Requires approval and may have conditions.","cat":"Land Use"},{"id":"c119","term":"Eminent Domain","def":"The government's power to take private property for public use. Requires just compensation (Fifth Amendment). The process is called condemnation.","cat":"Land Use"},{"id":"c120","term":"Police Power","def":"The government's authority to enact laws and regulations (zoning, building codes, health regulations) to protect public health, safety, and welfare.","cat":"Land Use"},{"id":"c121","term":"Building Codes","def":"Regulations setting minimum standards for construction, electrical, plumbing, and fire safety. Enforced through permits and inspections.","cat":"Land Use"},{"id":"c122","term":"Environmental Regulations","def":"Laws protecting the environment including lead paint disclosure (pre-1978), asbestos, radon, underground storage tanks, wetland protection, and Superfund (CERCLA).","cat":"Land Use"},{"id":"c123","term":"Lead-Based Paint Disclosure","def":"Federal law requires disclosure of known lead paint hazards and provision of an EPA pamphlet for properties built before 1978. Buyer gets 10 days for testing.","cat":"Land Use"},{"id":"c124","term":"Fair Housing Act","def":"Federal law prohibiting discrimination in housing based on race, color, religion, national origin, sex, familial status, and disability (seven protected classes).","cat":"Land Use"},{"id":"c125","term":"ADA in Real Estate","def":"The Americans with Disabilities Act requires reasonable accommodations in commercial properties and new multifamily construction (4+ units).","cat":"Land Use"},{"id":"c126","term":"Steering","def":"Directing buyers to or away from neighborhoods based on protected class membership. Illegal under the Fair Housing Act.","cat":"Land Use"},{"id":"c127","term":"Blockbusting","def":"Inducing owners to sell by suggesting that a protected class is moving into the neighborhood, implying property values will decline. Illegal.","cat":"Land Use"},{"id":"c128","term":"Redlining","def":"Refusing to lend or insure in specific neighborhoods based on racial or ethnic composition. Illegal under the Fair Housing Act and ECOA.","cat":"Land Use"},{"id":"c129","term":"Equal Credit Opportunity Act (ECOA)","def":"Prohibits discrimination in lending based on race, color, religion, national origin, sex, marital status, age, or receipt of public assistance.","cat":"Land Use"},{"id":"c130","term":"Property Tax","def":"An ad valorem (based on value) tax levied annually by local government. Calculated as assessed value × mill rate. Creates a specific lien if unpaid.","cat":"Land Use"},{"id":"c131","term":"Special Assessment","def":"A tax levied against properties benefiting from a public improvement (new sidewalk, sewer). Creates a specific lien on the assessed properties.","cat":"Land Use"},{"id":"c132","term":"Homestead Exemption","def":"State law protecting a portion of a homeowner's equity from creditors and providing property tax reduction. Amount and scope vary by state.","cat":"Land Use"},{"id":"c133","term":"Lease","def":"A contract granting possession and use of property for a specified time in exchange for rent. Creates a landlord-tenant relationship.","cat":"Leasing"},{"id":"c134","term":"Gross Lease","def":"The tenant pays a fixed rent; the landlord pays all operating expenses (taxes, insurance, maintenance). Common in residential.","cat":"Leasing"},{"id":"c135","term":"Net Lease","def":"The tenant pays base rent plus some or all operating expenses. NNN (triple net): tenant pays taxes, insurance, and maintenance. Common in commercial.","cat":"Leasing"},{"id":"c136","term":"Percentage Lease","def":"The tenant pays base rent plus a percentage of business income. Common in retail properties (malls, shopping centers).","cat":"Leasing"},{"id":"c137","term":"Estate for Years","def":"A lease with a definite beginning and ending date. No notice is needed to terminate — it ends automatically. Despite the name, can be any duration.","cat":"Leasing"},{"id":"c138","term":"Periodic Estate","def":"A lease that automatically renews for successive periods (month-to-month, year-to-year) until terminated with proper notice.","cat":"Leasing"},{"id":"c139","term":"Estate at Will","def":"A tenancy with no fixed term that either party may terminate at any time. Created by agreement or implied by circumstances.","cat":"Leasing"},{"id":"c140","term":"Estate at Sufferance","def":"A tenant remains after the lease expires without the landlord's consent. The tenant is a holdover and may be subject to eviction.","cat":"Leasing"},{"id":"c141","term":"Security Deposit","def":"Money held by the landlord as protection against damage or unpaid rent. State laws regulate the amount, holding requirements, and return timeline.","cat":"Leasing"},{"id":"c142","term":"Constructive Eviction","def":"When the landlord's actions (or inactions) make the property uninhabitable, effectively forcing the tenant to leave. The tenant must actually vacate to claim it.","cat":"Leasing"},{"id":"c143","term":"Actual Eviction","def":"The legal process by which a landlord removes a tenant for cause (nonpayment, lease violation). Requires proper notice and court proceedings.","cat":"Leasing"},{"id":"c144","term":"Sublease vs. Assignment","def":"Sublease: the original tenant leases to a third party but remains liable. Assignment: the original tenant transfers all rights; the new tenant deals directly with the landlord.","cat":"Leasing"},{"id":"c145","term":"Broker vs. Salesperson","def":"The broker holds the license that authorizes the brokerage. Salespersons must work under a supervising broker. The broker is responsible for the salesperson's actions.","cat":"Practice"},{"id":"c146","term":"Escrow","def":"A neutral third party holds documents and funds during a transaction. The escrow agent distributes them when all conditions are met (closing).","cat":"Practice"},{"id":"c147","term":"Closing / Settlement","def":"The meeting where the transaction is completed: documents are signed, funds are distributed, and title transfers. The deed is delivered and recorded.","cat":"Practice"},{"id":"c148","term":"Proration","def":"Dividing expenses (taxes, HOA dues, rent, interest) between buyer and seller based on the date of closing. Each party pays their share.","cat":"Practice"},{"id":"c149","term":"TRID (TILA-RESPA Integrated Disclosure)","def":"Federal regulation combining mortgage disclosures: the Loan Estimate (within 3 days of application) and the Closing Disclosure (3 days before closing).","cat":"Practice"},{"id":"c150","term":"Multiple Listing Service (MLS)","def":"A shared database where brokers list properties and offer cooperation and compensation to other brokers. Increases exposure and efficiency.","cat":"Practice"},{"id":"c151","term":"Comparative Market Analysis (CMA)","def":"A broker's informal estimate of a property's value using recent comparable sales, active listings, and expired listings. Not an appraisal.","cat":"Practice"},{"id":"c152","term":"Antitrust Laws","def":"Prohibit price-fixing (agreeing on commission rates), market allocation (dividing territories), group boycotts, and tie-in arrangements. Violations carry criminal penalties.","cat":"Practice"},{"id":"c153","term":"Do Not Call Registry","def":"Federal list of consumers who do not wish to receive telemarketing calls. Real estate agents must comply unless an existing relationship or FSBO exemption applies.","cat":"Practice"},{"id":"c154","term":"E&O Insurance","def":"Errors and Omissions insurance protects real estate professionals against claims of negligence, errors, or omissions in their professional services.","cat":"Practice"},{"id":"c155","term":"Trust Account","def":"A separate bank account where the broker holds client funds (earnest money, security deposits). Required by law; cannot be commingled with the broker's funds.","cat":"Practice"}],"questions":[{"cat":"Agency","stem":"A listing agent learns that the property has a cracked foundation. The agent must:","choices":["Disclose only if asked","Keep it confidential per the seller's instructions","Disclose this to potential buyers","Only disclose to the buyer's agent"],"answer":2,"label":"Material fact disclosure","why":"Material defects must be disclosed to all parties regardless of client instructions. This duty overrides confidentiality.","id":"q031","n":31},{"cat":"Contracts","stem":"A buyer makes an offer on a property. Before the seller responds, the buyer withdraws the offer. This is:","choices":["Not permitted once an offer is made","Permitted — an offer can be revoked any time before acceptance","A breach of contract","Only allowed if the seller agrees"],"answer":1,"label":"Offer revocation","why":"An offer can be revoked at any time before acceptance is communicated. There is no binding contract until acceptance.","id":"q021","n":21},{"cat":"Financing","stem":"The document that creates the debt obligation is:","choices":["The promissory note","The deed of trust","The deed","The mortgage"],"answer":0,"label":"Promissory note","why":"The promissory note is the borrower's promise to repay. The mortgage or deed of trust is the security instrument pledging the property as collateral.","id":"q041","n":41},{"cat":"Land Use","stem":"A homeowner wants to build a taller fence than zoning allows. They should apply for:","choices":["A rezoning","A building permit only","A conditional use permit","A variance"],"answer":3,"label":"Variance for exception","why":"A variance grants an exception to a specific zoning requirement for a particular property due to hardship.","id":"q059","n":59},{"cat":"Leasing","stem":"A lease that automatically renews each month until either party gives notice is:","choices":["An estate at will","An estate for years","A periodic estate","An estate at sufferance"],"answer":2,"label":"Periodic estate","why":"A periodic estate (month-to-month) renews automatically until terminated with proper notice.","id":"q067","n":67},{"cat":"Practice","stem":"All real estate salespersons must work under:","choices":["A supervising broker","The local real estate board","No supervision is required after licensing","Their own license"],"answer":0,"label":"Broker supervision","why":"Salespersons cannot operate independently. They must be affiliated with and supervised by a licensed broker.","id":"q073","n":73},{"cat":"Property","stem":"A buyer purchases a home and discovers the seller removed a built-in dishwasher that was not excluded in the contract. The dishwasher is:","choices":["A trade fixture belonging to the seller","Not covered by the purchase agreement","A fixture that conveys with the property unless specifically excluded","Personal property the seller was entitled to take"],"answer":2,"label":"Fixture conveys","why":"A built-in appliance is permanently attached and is a fixture. Fixtures convey with the property unless the contract specifically excludes them.","id":"q001","n":1},{"cat":"Title","stem":"A property has three liens: a first mortgage recorded in 2020, a property tax lien from 2023, and a mechanic's lien filed in 2022. In a foreclosure sale, which lien has FIRST priority?","choices":["They share equal priority","The first mortgage","The property tax lien","The mechanic's lien"],"answer":2,"label":"Tax lien priority","why":"Property tax liens take priority over all other liens regardless of recording date.","id":"q011","n":11},{"cat":"Valuation","stem":"The appraisal method MOST commonly used for single-family residential properties is:","choices":["The gross rent multiplier","The income approach","The sales comparison approach","The cost approach"],"answer":2,"label":"Sales comparison for residential","why":"The sales comparison approach compares the subject to recent comparable sales and is the primary method for residential appraisal.","id":"q051","n":51},{"cat":"Agency","stem":"The fiduciary duties owed to a client are remembered by the acronym:","choices":["TILA","ECOA","RESPA","OLDCAR"],"answer":3,"label":"OLDCAR","why":"Obedience, Loyalty, Disclosure, Confidentiality, Accountability, Reasonable care — the agent's fiduciary duties to their client.","id":"q032","n":32}],"meta":{"total":94,"free":10,"split":true}};
